package dev.slithergoh.pixelmonradar.client;
import com.mojang.blaze3d.vertex.*;import com.pixelmonmod.pixelmon.entities.pixelmon.PixelmonEntity;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.core.BlockPos;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemDisplayContext;import net.minecraft.world.item.ItemStack;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.client.gui.Font;import org.joml.Matrix4f;import net.minecraft.world.phys.Vec3;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderLevelStageEvent;import java.util.OptionalDouble;
@EventBusSubscriber(modid="pixelmonradar",value=Dist.CLIENT)public final class OreWorldRenderer{private static final RenderType ESP_LINES=EspRenderType.linesNoDepth();
 @SubscribeEvent public static void render(RenderLevelStageEvent e){if(e.getStage()!=RenderLevelStageEvent.Stage.AFTER_CUTOUT_MIPPED_BLOCKS_BLOCKS)return;if(!RadarSettings.oreEspEnabled&&RadarSettings.trackedEntityId==-1)return;Minecraft mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return;Vec3 cam=mc.gameRenderer.getMainCamera().getPosition();PoseStack ps=e.getPoseStack();ps.pushPose();ps.translate(-cam.x,-cam.y,-cam.z);MultiBufferSource.BufferSource bs=mc.renderBuffers().bufferSource();RenderType esp=ESP_LINES;VertexConsumer vc=bs.getBuffer(esp);int count=0;if(RadarSettings.oreEspEnabled)for(BlockPos p:OreScanner.scan()){if(count++>=1200)break;ResourceLocation id=BuiltInRegistries.BLOCK.getKey(mc.level.getBlockState(p).getBlock());float[]c=color(id);double d=Math.sqrt(p.distSqr(mc.player.blockPosition()));float pulse=RadarSettings.espAnimation?(float)(.94+.06*Math.sin(System.currentTimeMillis()/420.0+d*.22)):1f;float fade=(float)Math.max(.42,1.0-d/Math.max(12,RadarSettings.oreRange)*.38);float a=Math.min(1f,fade*pulse);double pad=.025+.012*(1-pulse);LevelRenderer.renderLineBox(ps,vc,p.getX()-pad,p.getY()-pad,p.getZ()-pad,p.getX()+1+pad,p.getY()+1+pad,p.getZ()+1+pad,c[0],c[1],c[2],a,c[0],c[1],c[2]);if(RadarSettings.espGlow&&d<=RadarSettings.espDetailRange&&count<=40){double q=.075+.025*(1-pulse);LevelRenderer.renderLineBox(ps,vc,p.getX()-q,p.getY()-q,p.getZ()-q,p.getX()+1+q,p.getY()+1+q,p.getZ()+1+q,c[0],c[1],c[2],a*.22f,c[0],c[1],c[2]);}}for(PokemonInfo rare:PokemonScanner.scan())if(rare.rare()){var re=mc.level.getEntity(rare.entityId());if(re instanceof PixelmonEntity rp){var rb=rp.getBoundingBox().inflate(.08);float[]rc=rare.shiny()?new float[]{1f,.82f,.18f}:rare.legendary()||rare.mythical()?new float[]{1f,.55f,.15f}:rare.boss()?new float[]{1f,.2f,.12f}:new float[]{.7f,.25f,1f};float pa=(float)(.65+.35*Math.sin(System.currentTimeMillis()/190.0));LevelRenderer.renderLineBox(ps,vc,rb.minX,rb.minY,rb.minZ,rb.maxX,rb.maxY,rb.maxZ,rc[0],rc[1],rc[2],pa,rc[0],rc[1],rc[2]);}}if(RadarSettings.trackedEntityId!=-1){var entity=mc.level.getEntity(RadarSettings.trackedEntityId);if(entity instanceof PixelmonEntity pokemon){var box=pokemon.getBoundingBox().inflate(.12);boolean shiny=pokemon.getPokemon()!=null&&pokemon.getPokemon().isShiny();float pulse=(float)(.78+.22*Math.sin(System.currentTimeMillis()/180.0));float rr=shiny?1f:.2f,gg=shiny?.82f:.85f,bb=shiny?.18f:1f;double q=.10+.08*(1-pulse);LevelRenderer.renderLineBox(ps,vc,box.minX-q,box.minY-q,box.minZ-q,box.maxX+q,box.maxY+q,box.maxZ+q,rr,gg,bb,1f,rr,gg,bb);LevelRenderer.renderLineBox(ps,vc,box.minX-.24,box.minY-.24,box.minZ-.24,box.maxX+.24,box.maxY+.24,box.maxZ+.24,rr,gg,bb,.25f,rr,gg,bb);}}bs.endBatch(esp);if(RadarSettings.oreEspEnabled&&RadarSettings.espLabels)renderLabels(mc,ps,bs);ps.popPose();}
 private static void renderLabels(Minecraft mc,PoseStack ps,MultiBufferSource.BufferSource bs){java.util.HashSet<String>groups=new java.util.HashSet<>();int shown=0;for(BlockPos p:OreScanner.scan()){if(shown>=Math.min(RadarSettings.espMaxIcons,18))break;double d=Math.sqrt(p.distSqr(mc.player.blockPosition()));if(d>RadarSettings.espDetailRange)continue;ResourceLocation id=BuiltInRegistries.BLOCK.getKey(mc.level.getBlockState(p).getBlock());String group=id.toString()+":"+(p.getX()>>2)+":"+(p.getY()>>2)+":"+(p.getZ()>>2);if(!groups.add(group))continue;ItemStack stack=new ItemStack(mc.level.getBlockState(p).getBlock().asItem());String name=stack.isEmpty()?title(id.getPath()):stack.getHoverName().getString();int cluster=0;for(BlockPos q:OreScanner.scan())if(q.distSqr(p)<=18&&mc.level.getBlockState(q).getBlock()==mc.level.getBlockState(p).getBlock())cluster++;String label=name+(cluster>1?" ×"+cluster:"")+"  •  "+Math.round(d)+"m";float[]c=color(id);int rgb=0xFF000000|((int)(c[0]*255)<<16)|((int)(c[1]*255)<<8)|(int)(c[2]*255);ps.pushPose();ps.translate(p.getX()+.5,p.getY()+1.16,p.getZ()+.5);ps.mulPose(mc.gameRenderer.getMainCamera().rotation());float scale=(float)(.0165*Math.max(.92,Math.min(1.22,d/16.0)));ps.scale(-scale,-scale,scale);Matrix4f matrix=ps.last().pose();float x=-mc.font.width(label)/2f;mc.font.drawInBatch(label,x+1,1,0xAA000000,false,matrix,bs,Font.DisplayMode.SEE_THROUGH,0xB0000000,15728880);mc.font.drawInBatch(label,x,0,rgb,false,matrix,bs,Font.DisplayMode.SEE_THROUGH,0xA8000000,15728880);ps.popPose();shown++;}bs.endBatch();}
 private static String title(String s){StringBuilder o=new StringBuilder();boolean up=true;for(char ch:s.toCharArray()){if(ch=='_'){o.append(' ');up=true;}else{o.append(up?Character.toUpperCase(ch):ch);up=false;}}return o.toString();}
 private static final class EspRenderType extends RenderType{private EspRenderType(String n,VertexFormat f,VertexFormat.Mode m,int b,boolean a,boolean c,Runnable s,Runnable e){super(n,f,m,b,a,c,s,e);}static RenderType linesNoDepth(){CompositeState state=CompositeState.builder().setShaderState(RENDERTYPE_LINES_SHADER).setLineState(new LineStateShard(OptionalDouble.of(2.5))).setLayeringState(VIEW_OFFSET_Z_LAYERING).setTransparencyState(TRANSLUCENT_TRANSPARENCY).setOutputState(ITEM_ENTITY_TARGET).setWriteMaskState(COLOR_WRITE).setCullState(NO_CULL).setDepthTestState(NO_DEPTH_TEST).createCompositeState(false);return create("atlas_esp_lines_no_depth",DefaultVertexFormat.POSITION_COLOR_NORMAL,VertexFormat.Mode.LINES,256,state);}}
 private static float[]color(ResourceLocation id){String p=id.getPath();if(p.contains("pokestop")||p.contains("poke_stop"))return new float[]{.15f,.75f,1f};if(p.contains("pokeloot")||p.contains("poke_loot")||p.contains("pokeball")||p.contains("poke_ball"))return new float[]{1f,.2f,.25f};if(p.contains("diamond")||p.contains("crystal"))return new float[]{.2f,1f,1f};if(p.contains("emerald"))return new float[]{.2f,1f,.35f};if(p.contains("redstone")||p.contains("ruby"))return new float[]{1f,.15f,.15f};if(p.contains("lapis")||p.contains("sapphire"))return new float[]{.2f,.4f,1f};if(p.contains("gold"))return new float[]{1f,.8f,.1f};if(p.contains("iron")||p.contains("silver")||p.contains("platinum"))return new float[]{.9f,.9f,.9f};if(p.contains("copper")||p.contains("bauxite"))return new float[]{1f,.45f,.18f};if(p.contains("coal"))return new float[]{.55f,.55f,.55f};return new float[]{1f,.3f,.8f};}}
